CREATE TABLE IF NOT EXISTS editions (id text PRIMARY KEY, label text NOT NULL UNIQUE CHECK(length(label) BETWEEN 1 AND 80), start_day date NOT NULL, end_day date NOT NULL CHECK(end_day >= start_day));
CREATE TABLE scheduling_state (id integer PRIMARY KEY CHECK(id=1), revision bigint NOT NULL DEFAULT 0, current_edition text REFERENCES editions(id));
INSERT INTO scheduling_state(id) VALUES(1);
CREATE TABLE accounts (id text PRIMARY KEY, issuer text NOT NULL, subject text NOT NULL, UNIQUE(issuer,subject));
CREATE TABLE global_grants (account_id text PRIMARY KEY REFERENCES accounts(id));
CREATE TABLE stands (id text PRIMARY KEY, name text NOT NULL CHECK(length(name) BETWEEN 1 AND 120));
CREATE TABLE participations (id text PRIMARY KEY, edition_id text NOT NULL REFERENCES editions(id), stand_id text NOT NULL REFERENCES stands(id), enabled boolean NOT NULL DEFAULT true, UNIQUE(edition_id,stand_id));
CREATE TABLE teams (participation_id text REFERENCES participations(id), account_id text REFERENCES accounts(id), PRIMARY KEY(participation_id,account_id));
CREATE TABLE workers (id text PRIMARY KEY, first_name text NOT NULL CHECK(length(first_name) BETWEEN 1 AND 120), last_name text NOT NULL CHECK(length(last_name) BETWEEN 1 AND 120), email text NOT NULL DEFAULT '', phone text NOT NULL DEFAULT '', notes text NOT NULL DEFAULT '', account_id text UNIQUE REFERENCES accounts(id));
CREATE TABLE memberships (stand_id text REFERENCES stands(id), worker_id text REFERENCES workers(id), PRIMARY KEY(stand_id,worker_id));
CREATE TABLE shifts (id text PRIMARY KEY, participation_id text NOT NULL REFERENCES participations(id), title text NOT NULL CHECK(length(title) BETWEEN 1 AND 120), starts_at timestamptz NOT NULL, ends_at timestamptz NOT NULL CHECK(ends_at>starts_at), capacity integer NOT NULL CHECK(capacity>0), cancelled boolean NOT NULL DEFAULT false, version integer NOT NULL DEFAULT 1);
CREATE INDEX shifts_schedule ON shifts(participation_id,starts_at);
CREATE TABLE requests (id text PRIMARY KEY, shift_id text NOT NULL REFERENCES shifts(id), worker_id text NOT NULL REFERENCES workers(id), status text NOT NULL CHECK(status IN ('pending','approved','declined','withdrawn','cancelled')), shift_version integer NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(shift_id,worker_id));
CREATE TABLE assignments (shift_id text REFERENCES shifts(id), worker_id text REFERENCES workers(id), active boolean NOT NULL DEFAULT true, PRIMARY KEY(shift_id,worker_id));
CREATE TABLE capabilities (digest text PRIMARY KEY, kind text NOT NULL CHECK(kind IN ('signup','connection','fresh','organizer')), participation_id text REFERENCES participations(id), shift_id text REFERENCES shifts(id), worker_id text REFERENCES workers(id), issuer_id text REFERENCES accounts(id), scope text NOT NULL DEFAULT '', expires_at timestamptz, disabled boolean NOT NULL DEFAULT false, consumed_by text REFERENCES accounts(id), created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE submissions (key text PRIMARY KEY, fingerprint text NOT NULL, worker_id text NOT NULL REFERENCES workers(id), connection_token text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE scheduling_audit (id bigserial PRIMARY KEY, actor text NOT NULL, action text NOT NULL, resource text NOT NULL, details jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX requests_worker ON requests(worker_id);
CREATE INDEX memberships_worker ON memberships(worker_id);
CREATE INDEX teams_account ON teams(account_id);
